export function getQuestionsByWeekEng12(weekNum) {
  return QUESTION_BANK_ENG12.filter(q => q.week === Number(weekNum));
}

export function getFilteredQuestionsEng12(filters = {}) {
  return QUESTION_BANK_ENG12.filter(q => {
    if (filters.stage && q.stage !== Number(filters.stage)) return false;
    if (filters.difficulty && filters.difficulty !== 'all' && q.difficulty !== filters.difficulty) return false;
    if (filters.category && filters.category !== 'all' && q.category !== filters.category) return false;
    if (filters.semester && q.semester !== Number(filters.semester)) return false;
    return true;
  });
}
